import{z as B,x as p,o as E,c as A,q as t,j as l,D as e,d as o,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"livepatch","description":"","frontmatter":{"title":"livepatch","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/livepatch.md","filePath":"cs/livepatch.md","lastUpdated":1791413859000}'),c={name:"cs/livepatch.md"};function n(h,a,d,_,C,f){const i=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="livepatch" tabindex="-1">livepatch <a class="header-anchor" href="#livepatch" aria-label="Permalink to &quot;livepatch&quot;">​</a></h1><div class="epigraph"><p>livepatch 把函数入口改成跳转到新实现，使安全修复不必重启；一致性模型决定何时所有任务都看见新函数。</p><footer>—— 据 Linux livepatch 文档；[kprobes](/cs/kprobes-uprobes) 为改指令先修；kABI 后课</footer></div><p><a href="/cs/oops-panic">oops</a> 的修复通常要重启。缺口是 <strong>不停机打补丁</strong>：ftrace 或 jmp，过渡态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>替换 <code>foo</code> → 新 <code>foo</code>。旧栈上的任务仍在旧函数。缺口：可靠性模型（等待安全点）；与 CFI；不能改数据结构布局——那是 kABI。本课不把厂商补丁流程写成运维手册。</p><p><span class="marginnote">直觉类比：livepatch 像飞行中换引擎——不是造架新飞机（重启），而是在旧引擎（旧函数）入口装导流板，让新来的气流（新调用）改走新引擎；要等旧引擎里没有还在转的叶片（没有在途任务）才算换完。</span></p><p><span class="marginnote">KGraft/kpatch 历史不同模型。对象是函数级替换，不是容器滚动发布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载模块 → 注册替换表 → 启用。对照 kprobe：临时 vs 持久替换。对照 <a href="/cs/fuse">FUSE</a>：用户升级守护即可；内核不行。对照 Secure Boot：模块仍要签名——后课。</p>',9)),(E(),l(s,null,{default:e(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E5%87%BD%E6%95%B0%22%5D%20--%3E%20JMP%5B%22%E5%85%A5%E5%8F%A3%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20JMP%20--%3E%20NEW%5B%22%E6%96%B0%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20TASK%5B%22%E5%9C%A8%E9%80%94%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20WAIT%5B%22%E7%AD%89%E5%88%B0%E5%AE%89%E5%85%A8%E7%82%B9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>livepatch 用指令替换换重启窗口，服务高可用。它不能魔法般迁移堆上的结构体。不要写成零风险。与 <a href="/cs/sched-ext">sched_ext</a>：BPF 程序可卸载；livepatch 更敏感。</p><p><span class="marginnote">常见误区：以为补丁想怎么改就怎么改。livepatch 只能整函数替换——不能改结构体布局、不能改函数签名，否则新旧代码对同一块内存的理解就对不上；那是 kABI 的约束，另课处理。</span></p><p>失败的补丁比漏洞更糟，要回滚路径。</p><p>实现上：一致性模型若等所有任务离开旧函数，持锁睡眠的任务会挡住打补丁。只能替换函数，不能改结构体布局。签名与 kABI 约束和普通模块相同。 读法上只引用<a href="/cs/oops-panic">上一课</a>的结论，不把对象换成训练推理或限价簿。</p>',5)),(E(),l(s,null,{default:e(()=>[r(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E4%BB%BB%E5%8A%A1%20A%20%E8%BF%9B%E5%85%A5%E6%97%A7%20foo%EF%BC%8C%E7%9D%A1%E5%9C%A8%E6%8C%81%E9%94%81%E8%B7%AF%E5%BE%84%E4%B8%8A%22%5D%20--%3E%20EN%5B%22%E6%89%93%E8%A1%A5%E4%B8%81%EF%BC%9Afoo%20%E5%85%A5%E5%8F%A3%E6%94%B9%E6%88%90%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20EN%20--%3E%20NEW%5B%22%E6%AD%A4%E5%90%8E%E6%96%B0%E8%B0%83%E7%94%A8%E4%B8%80%E5%BE%8B%E8%BF%9B%E6%96%B0%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20EN%20--%3E%20CHK%7B%22%E6%97%A7%E5%87%BD%E6%95%B0%E9%87%8C%E8%BF%98%E6%9C%89%E5%9C%A8%E9%80%94%E4%BB%BB%E5%8A%A1%E5%90%97%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%9C%89%22%7C%20TRANS%5B%22%E8%A1%A5%E4%B8%81%E4%BF%9D%E6%8C%81%E8%BF%87%E6%B8%A1%E6%80%81%EF%BC%8C%E7%BB%A7%E7%BB%AD%E7%AD%89%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%97%A0%22%7C%20DONE%5B%22%E6%89%80%E6%9C%89%E4%BB%BB%E5%8A%A1%E4%B8%80%E8%87%B4%EF%BC%9A%E8%A1%A5%E4%B8%81%E7%BD%AE%E4%B8%BA%E5%B7%B2%E5%AE%8C%E6%88%90%22%5D%0A%20%20TRANS%20--%3E%20CHK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">为什么重要：一个持锁睡上几秒的任务就能把补丁卡在过渡态，生产上要挑低负载窗口或换更宽松的一致性模型；失败的补丁比漏洞更糟，所以加载前校验与回滚路径是硬要求。</span></p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>livepatch</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 arch 的 ftrace 调用约定。不保证实时系统的安全点延迟。下一课如何得到可加载的内核：配置与编译。</p><p>版本字段会变，课序钉的是机制对象「livepatch」，不是某一主线内核的结构体名。 后课默认：函数可在运行时替换。内核配置与构建，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>livepatch 跳转到新函数，等待一致性。</li><li>不改变数据结构布局。</li><li>内核配置编译是下一课。</li><li>出处：Linux livepatch；kpatch 背景。</li></ul>',8))])}const D=B(c,[["render",n]]);export{u as __pageData,D as default};
